/* Actual explorer and actual diff process. Only owned windows and messages. */
#define COBJMACROS
#define wWinMain diff_unused_host_entrypoint
#include "../app/fpdemo.c"
#undef wWinMain
static int passed,failed;static wchar_t left[32768],right[32768];
#define CHECK(label,c) do{if(c){passed++;printf("ok %s\n",label);}else{failed++;printf("FAIL line %d: %s\n",__LINE__,label);}}while(0)
static void pump_diff(int ms){uint64_t end=GetTickCount64()+ms;do{MSG m;while(PeekMessageW(&m,NULL,0,0,PM_REMOVE))if(m.message!=WM_QUIT){TranslateMessage(&m);DispatchMessageW(&m);}Sleep(2);}while(GetTickCount64()<end);}
static int wait_diff(uint64_t session){uint64_t end=GetTickCount64()+12000;while((g_diff_state.session!=session||g_diff_state.state!=DIFF_READY)&&GetTickCount64()<end)pump_diff(5);return g_diff_state.session==session&&g_diff_state.state==DIFF_READY;}
static int cursor_named(Pane *p,const wchar_t *name){for(uint32_t i=0;i<p_count(p);i++){const fpe_entry *e=fpe_view_at(p->view,i);if(e&&!wcscmp(fpe_view_name(p->view,i),name)){p->cursor=i;p->nsel=0;return 1;}}return 0;}
static void test_diff_host_pair_capture_orientation_and_command(void){CHECK("diff helper stays dormant during browsing",!sidepanel_running(diff_app()));CHECK("one comparison file in each real pane",cursor_named(&g.panes[0],L"left.txt")&&cursor_named(&g.panes[1],L"right.txt"));set_active(1);fn_ctx c;app_pane_ctx(&c,&g.panes[1],FN_FROM_CODE);CHECK("Compare files is offered for the two selected files",diff_applies(&c));fn_run(fn_find("file.compare_files"),&c);app_ctx_free(&c);uint64_t session=g_diff_request.session;CHECK("real diff helper completes from normal function dispatch",wait_diff(session)&&g_diff_state.hunks==1&&!g_diff_state.bytes_equal);wchar_t a[32768],b[32768];swprintf(a,32768,L"%ls\\left.txt",left);swprintf(b,32768,L"%ls\\right.txt",right);CHECK("active right pane does not reverse left/right orientation",g_diff_paths[0]&&g_diff_paths[1]&&fpe_path_equal(g_diff_paths[0],a)&&fpe_path_equal(g_diff_paths[1],b));cursor_named(&g.panes[1],L"other.txt");CHECK("later cursor movement cannot change the frozen pair",fpe_path_equal(g_diff_paths[1],b)&&g_diff_request.session==session);}
static void test_diff_host_hidden_results_replacement_and_stale_state(void){uint32_t launch=sidepanel_generation(diff_app());uint64_t session=g_diff_request.session;sidepanel_close();pump_diff(30);pane_run(active_pane(),"diff.show",FN_FROM_CODE);pump_diff(30);CHECK("hidden comparison reuses authenticated owned helper and result",sidepanel_generation(diff_app())==launch&&g_diff_request.session==session&&g_diff_state.state==DIFF_READY);diff_state fake={.session=session-1,.state=DIFF_FAILED,.error=123};panel_message(diff_app(),PANELP_DIFF_STATE,&fake,sizeof fake);CHECK("stale session reports cannot replace current result",g_diff_state.session==session&&g_diff_state.state==DIFF_READY);fn_ctx c;app_pane_ctx(&c,&g.panes[1],FN_FROM_CODE);fn_run(fn_find("file.compare_files"),&c);app_ctx_free(&c);CHECK("new selected pair replaces the existing comparison",g_diff_request.session>session&&wait_diff(g_diff_request.session)&&g_diff_state.hunks==1&&sidepanel_generation(diff_app())==launch);}
static void test_diff_host_selection_rules_and_disabled_cleanup(void){fn_ctx c;app_pane_ctx(&c,&g.panes[0],FN_FROM_CODE);g.dual=0;CHECK("single pane cannot accidentally compare a hidden selection",!diff_applies(&c));g.dual=1;c.n=2;CHECK("multiple selected files are not a pair",!diff_applies(&c));c.n=1;c.state|=FN_S_DIR;CHECK("folder selections stay with folder comparison",!diff_applies(&c));app_ctx_free(&c);const char *settings="[functions]\nfile.compare_files = off\nsvc.shell = off\nsvc.icons = off\n[panel.side]\nslide = off\n";fn_settings(settings,strlen(settings));fn_configure_all();pump_diff(50);CHECK("disabling diff retires its process and captured paths",!sidepanel_running(diff_app())&&!g_diff_paths[0]&&!g_diff_paths[1]);char report[65536];fn_report_csv(report,sizeof report);CHECK("diff registry lifetime has no violations",strstr(report,"metric,fn_violations,,,,0,")!=NULL);}
int wmain(int argc,wchar_t **argv){if(argc!=3)return 2;wcsncpy(left,argv[1],32767);wcsncpy(right,argv[2],32767);CoInitializeEx(NULL,COINIT_APARTMENTTHREADED);SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);fn_host host={host_now,host_arm,host_status};fn_init(&host);CHECK("host commands fit the registry",!fn_register(app_functions,sizeof app_functions/sizeof *app_functions));functions_register();relay_register();palette_register();const char *settings="[functions]\nsvc.shell = off\nsvc.icons = off\n[panel.side]\nslide = off\n";fn_settings(settings,strlen(settings));fn_configure_all();g.engine=fpe_engine_create(NULL);g.dual=1;g.ratio=0.5;session_defaults(&g_ses);for(int i=0;i<2;i++){Pane *p=&g.panes[i];p->idx=i;p->ntabs=1;p->drop_row=-1;p->opts.dirs_first=1;}HINSTANCE instance=GetModuleHandleW(NULL);register_class(L"OpenPilot",main_proc,0,instance);register_class(L"OpenPilotPane",pane_proc,CS_DBLCLKS,instance);register_class(L"OpenPilotTree",tree_proc,CS_DBLCLKS,instance);register_class(L"OpenPilotDebug",dbg_proc,0,instance);HWND window=CreateWindowExW(0,L"OpenPilot",L"Owned diff integration",WS_OVERLAPPEDWINDOW|WS_CLIPCHILDREN,80,80,1300,850,NULL,NULL,instance,NULL);if(!window)return 3;for(int i=0;i<2;i++){fpe_dir *dir=read_start(i?right:left);if(dir){p_show_dir(&g.panes[i],dir,NULL,0);fpe_dir_release(dir);}}ShowWindow(window,SW_SHOWNOACTIVATE);UpdateWindow(window);pump_diff(20);test_diff_host_pair_capture_orientation_and_command();test_diff_host_hidden_results_replacement_and_stale_state();test_diff_host_selection_rules_and_disabled_cleanup();DestroyWindow(window);pump_diff(100);settings_save_join();folderwatch_join();fpe_engine_destroy(g.engine);CoUninitialize();printf("%d passed, %d failed; 3 diff host selectors\n",passed,failed);return failed?1:0;}
